const redis1 = JSON.parse($json.Redis1);
const redis2 = JSON.parse($json.Redis2);

const combinadoSemDuplicatas = Array.from(new Set([...redis1, ...redis2]));

const mensagem = combinadoSemDuplicatas.join(" ");

return [{ json: { mensagem_completa: mensagem } }];

// Pegamos os dois campos de onde o WhatsApp envia os JIDs
const jid1 = $input.first().json.body.data.key.remoteJid || "";
const jid2 = $input.first().json.body.data.key.remoteJidAlt || "";

// Variável onde vamos guardar o correto
let correctJid = "";

// Testa qual deles possui "@s.whatsapp.net"
if (jid1.includes("@s.whatsapp.net")) {
  correctJid = jid1;
} else if (jid2.includes("@s.whatsapp.net")) {
  correctJid = jid2;
}

// Retornamos somente o que é válido
return [
  {
    json: {
      selectedNumber: correctJid
    }
  }
];

let rawText = $input.first().json.Resposta || $input.first().json.output || '';

// Limpa pensamentos internos e preâmbulos em inglês se houver
if (rawText.includes('We have a problem') || rawText.includes('Let\'s produce') || rawText.includes('Need to correct')) {
  const match = rawText.match(/(Olá[\s\S]*|Oi[\s\S]*|Seu agendamento[\s\S]*)/i);
  if (match) {
    rawText = match[0];
  }
}

// Remove separadores esquisitos, pontos soltos e traços
rawText = rawText.replace(/^[-\\s*~._]{3,}$/gm, '');
rawText = rawText.replace(/\n{3,}/g, '\n\n');
rawText = rawText.trim();

if (!rawText) return [];

// Se a mensagem tiver até 800 caracteres, envia como mensagem única elegante
if (rawText.length <= 800) {
  return [{ json: { output: rawText } }];
}

// Se for maior, divide por parágrafos naturais
const paragraphs = rawText.split(/\n\n+/).map(p => p.trim()).filter(p => p.length > 0);
return paragraphs.map(p => ({ json: { output: p } }));
